with card_content(display_order, question_text, question_translation, answer_examples) as (
  values
    (81, 'What makes you laugh?', 'O que faz você rir?', '[{"answer":"Funny movies make me laugh.","translation":"Filmes engraçados me fazem rir.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"My friends make me laugh a lot.","translation":"Meus amigos me fazem rir muito.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I laugh at silly jokes.","translation":"Eu rio de piadas bobas.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Unexpected situations often make me laugh.","translation":"Situações inesperadas frequentemente me fazem rir.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I laugh most when I''m relaxed and talking with people I know well.","translation":"Eu rio mais quando estou relaxado/a e conversando com pessoas que conheço bem.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (82, 'What helps you relax?', 'O que ajuda você a relaxar?', '[{"answer":"Listening to music helps me relax.","translation":"Ouvir música me ajuda a relaxar.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I relax by taking a walk.","translation":"Eu relaxo fazendo uma caminhada.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Reading helps me unwind.","translation":"Ler me ajuda a relaxar.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I like watching a series after work.","translation":"Eu gosto de assistir a uma série depois do trabalho.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"A quiet evening at home with no plans helps me relax the most.","translation":"Uma noite tranquila em casa, sem planos, é o que mais me ajuda a relaxar.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (83, 'What are you afraid of?', 'Do que você tem medo?', '[{"answer":"I''m afraid of heights.","translation":"Eu tenho medo de altura.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''m scared of snakes.","translation":"Eu tenho medo de cobras.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I don''t like flying very much.","translation":"Eu não gosto muito de voar.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I''m afraid of losing people I love.","translation":"Eu tenho medo de perder pessoas que amo.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I have a few fears, but I try not to let them control my decisions.","translation":"Eu tenho alguns medos, mas tento não deixar que controlem minhas decisões.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (84, 'What are you proud of?', 'Do que você se orgulha?', '[{"answer":"I''m proud of my family.","translation":"Eu me orgulho da minha família.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''m proud of my career.","translation":"Eu me orgulho da minha carreira.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''m proud of finishing my degree.","translation":"Eu me orgulho de ter concluído minha graduação.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I''m proud of how much I''ve learned.","translation":"Eu me orgulho do quanto aprendi.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''m especially proud of the challenges I''ve overcome in the last few years.","translation":"Eu me orgulho especialmente dos desafios que superei nos últimos anos.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (85, 'What is something you are good at?', 'Em que você é bom/boa?', '[{"answer":"I''m good at cooking.","translation":"Eu sou bom/boa em cozinhar.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''m good at solving problems.","translation":"Eu sou bom/boa em resolver problemas.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''m good at organizing things.","translation":"Eu sou bom/boa em organizar coisas.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I''m pretty good at explaining ideas.","translation":"Eu sou bastante bom/boa em explicar ideias.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''d say I''m good at staying calm and finding practical solutions.","translation":"Eu diria que sou bom/boa em manter a calma e encontrar soluções práticas.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (86, 'What would you like to learn?', 'O que você gostaria de aprender?', '[{"answer":"I''d like to learn Spanish.","translation":"Eu gostaria de aprender espanhol.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I want to learn how to play the piano.","translation":"Eu quero aprender a tocar piano.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''d like to improve my English.","translation":"Eu gostaria de melhorar meu inglês.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I want to learn more about technology.","translation":"Eu quero aprender mais sobre tecnologia.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''d like to learn a skill that I can use both at work and in my personal life.","translation":"Eu gostaria de aprender uma habilidade que possa usar tanto no trabalho quanto na vida pessoal.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (87, 'What is something new you learned recently?', 'O que você aprendeu de novo recentemente?', '[{"answer":"I learned a new English expression.","translation":"Eu aprendi uma expressão nova em inglês.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I learned how to make a new recipe.","translation":"Eu aprendi a fazer uma receita nova.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I recently learned a new feature at work.","translation":"Eu aprendi recentemente um recurso novo no trabalho.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I learned a better way to organize my schedule.","translation":"Eu aprendi uma maneira melhor de organizar minha agenda.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Recently, I learned something useful about a topic I''d been curious about for a long time.","translation":"Recentemente, aprendi algo útil sobre um assunto pelo qual eu tinha curiosidade há muito tempo.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (88, 'What was your favorite subject at school?', 'Qual era a sua matéria favorita na escola?', '[{"answer":"My favorite subject was English.","translation":"Minha matéria favorita era inglês.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I liked history the most.","translation":"Eu gostava mais de história.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Math was my favorite subject.","translation":"Matemática era a minha matéria favorita.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I really enjoyed geography.","translation":"Eu gostava muito de geografia.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I liked science because I enjoyed understanding how things work.","translation":"Eu gostava de ciências porque gostava de entender como as coisas funcionam.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (89, 'Did you enjoy school?', 'Você gostava da escola?', '[{"answer":"Yes, I did.","translation":"Sim, eu gostava.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Yes, I really enjoyed school.","translation":"Sim, eu gostava muito da escola.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Mostly, yes.","translation":"Na maior parte, sim.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Not very much, but I liked some subjects.","translation":"Não muito, mas eu gostava de algumas matérias.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I enjoyed learning, although I didn''t like every part of school life.","translation":"Eu gostava de aprender, embora não gostasse de todos os aspectos da vida escolar.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (90, 'What is your dream job?', 'Qual é o emprego dos seus sonhos?', '[{"answer":"My dream job is to be a teacher.","translation":"Meu emprego dos sonhos é ser professor/a.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''d love to work as a pilot.","translation":"Eu adoraria trabalhar como piloto.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"My dream is to run my own business.","translation":"Meu sonho é ter meu próprio negócio.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I''d like a job that lets me travel.","translation":"Eu gostaria de um trabalho que me permitisse viajar.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"My ideal job would be meaningful, flexible, and connected to something I enjoy.","translation":"Meu trabalho ideal seria significativo, flexível e ligado a algo de que eu gosto.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb)
)
update public.conversation_questions q set question_text=c.question_text,question_translation=c.question_translation,answer_examples=c.answer_examples from card_content c where q.display_order=c.display_order;
